import React, { useMemo } from 'react';
import { Box, Stack, Typography } from '@mui/material';
import { useLocation } from 'react-router-dom';
import { PAGE_BANNER_HIDDEN_ROUTES, resolvePageInfo } from '../utils/routePageMeta';
import { resolvePostLoginPageVisual } from '../utils/resolvePostLoginPageVisual';
import { resolveNavTopicIconForPath } from '../utils/resolveNavTopicIcon';
import { normalizeAssetUrl } from '../utils/normalizeAssetUrl';

interface PageInformationBannerProps {
  compact?: boolean;
}

const PageInformationBanner: React.FC<PageInformationBannerProps> = ({ compact = false }) => {
  const location = useLocation();
  const pathname = location.pathname || '/';
  const search = location.search || '';

  const pageInfo = useMemo(() => resolvePageInfo(pathname), [pathname]);
  const visual = useMemo(
    () => resolvePostLoginPageVisual(pathname, search),
    [pathname, search]
  );
  const topicIcon = useMemo(
    () => resolveNavTopicIconForPath(pathname, search),
    [pathname, search]
  );

  const imageSrc = normalizeAssetUrl(visual.image);

  if (PAGE_BANNER_HIDDEN_ROUTES.has(pathname)) {
    return null;
  }

  return (
    <Box
      component="section"
      aria-label={visual.title}
      sx={{
        mb: compact ? 0 : 0.5,
        borderRadius: 2,
        overflow: 'hidden',
        border: '1px solid',
        borderColor: 'divider',
        bgcolor: 'background.paper',
      }}
    >
      <Stack
        direction={{ xs: 'column', md: 'row' }}
        spacing={compact ? 1 : 1.5}
        alignItems={{ xs: 'stretch', md: 'flex-start' }}
        sx={{ p: compact ? 1.25 : 1.5 }}
      >
        <Stack
          direction="row"
          spacing={1.25}
          alignItems="flex-start"
          sx={{ flex: 1, minWidth: 0 }}
        >
          <Box
            aria-hidden
            sx={{
              mt: 0.25,
              color: 'primary.main',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              width: 36,
              height: 36,
              borderRadius: 1.5,
              bgcolor: 'action.hover',
              flexShrink: 0,
            }}
          >
            {topicIcon}
          </Box>
          <Stack spacing={0.5} sx={{ flex: 1, minWidth: 0 }}>
            <Typography
              component="h1"
              variant={compact ? 'subtitle1' : 'h6'}
              sx={{ fontWeight: 700, letterSpacing: 0.1, lineHeight: 1.3 }}
            >
              {pageInfo.title}
            </Typography>
            <Typography
              variant="body2"
              color="text.secondary"
              sx={{ lineHeight: 1.45, maxWidth: { md: '72ch' } }}
            >
              {pageInfo.pageDescription}
            </Typography>
          </Stack>
        </Stack>

        {imageSrc ? (
          <Box
            component="img"
            src={imageSrc}
            alt={visual.imageAlt}
            sx={{
              width: { xs: '100%', md: 280 },
              maxWidth: '100%',
              flexShrink: 0,
              display: 'block',
              borderRadius: 1.5,
              border: '1px solid',
              borderColor: 'divider',
              bgcolor: 'action.hover',
              minHeight: compact ? 96 : 120,
              maxHeight: compact ? { xs: 140, md: 160 } : { xs: 180, md: 200 },
              objectFit: 'contain',
              objectPosition: 'center',
            }}
          />
        ) : null}
      </Stack>
    </Box>
  );
};

export default PageInformationBanner;
