import React, { useEffect, useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { Alert, Box, Button, Stack, Typography } from '@mui/material';
import ApiService from '../services/api';
import RouteLoadingGate from './RouteLoadingGate';
import { isAdminPortalUser } from '../utils/authRole';

interface RequireMSMEProps {
    children: React.ReactNode;
}

const clearClientSession = () => {
    if (typeof window === 'undefined') {
        return;
    }
    try {
        localStorage.removeItem('token');
        localStorage.removeItem('msmeRegistration');
    } catch {
        /* ignore */
    }
};

/**
 * Wrapper component that checks if the current user has MSME data.
 * If user is MSME role but has no business data, redirects to registration.
 * Otherwise, renders children (the protected component).
 */
const RequireMSME: React.FC<RequireMSMEProps> = ({ children }) => {
    const navigate = useNavigate();
    const [loading, setLoading] = useState(true);
    const [hasMSME, setHasMSME] = useState(false);
    const [verificationFailed, setVerificationFailed] = useState(false);

    const checkMSMEStatus = useCallback(async () => {
        setVerificationFailed(false);

        if (isAdminPortalUser()) {
            navigate('/admin/dashboard', { replace: true });
            return;
        }

        try {
            const msmeResponse = await ApiService.getMSMEProfile();

            if (msmeResponse?.data) {
                setHasMSME(true);
            } else {
                navigate('/msme-registration');
            }
        } catch (error: unknown) {
            const status = (error as { response?: { status?: number } })?.response?.status;
            const message = String((error as Error)?.message || '').toLowerCase();

            if (message.includes('not found') || status === 404) {
                navigate('/msme-registration');
            } else if (status === 401 || status === 403) {
                clearClientSession();
                navigate('/login');
            } else {
                setHasMSME(false);
                setVerificationFailed(true);
            }
        } finally {
            setLoading(false);
        }
    }, [navigate]);

    useEffect(() => {
        checkMSMEStatus();
    }, [checkMSMEStatus]);

    if (loading) {
        return (
            <RouteLoadingGate message="Checking your company profile…" minHeight="400px" />
        );
    }

    if (verificationFailed) {
        return (
            <Box sx={{ p: 4, maxWidth: 480, mx: 'auto' }}>
                <Alert severity="warning" sx={{ mb: 2 }}>
                    We could not verify your company profile. Please try again in a moment.
                </Alert>
                <Stack direction="row" spacing={1}>
                    <Button
                        variant="contained"
                        onClick={() => {
                            setLoading(true);
                            void checkMSMEStatus();
                        }}
                    >
                        Retry
                    </Button>
                    <Button variant="text" onClick={() => navigate('/login')}>
                        Back to sign in
                    </Button>
                </Stack>
                <Typography variant="caption" color="text.secondary" sx={{ mt: 2, display: 'block' }}>
                    Reviewer accounts should use the admin &amp; reviewer portal instead.
                </Typography>
            </Box>
        );
    }

    return hasMSME ? <>{children}</> : null;
};

export default RequireMSME;
