import React, { useEffect, useState } from 'react';
import { Navigate } from 'react-router-dom';
import { Box, CircularProgress } from '@mui/material';
import ApiService from '../../services/api';
import { persistAdminPortalSession } from '../../utils/adminPortalSession';

interface AdminRouteProps {
    children: React.ReactNode;
}

/**
 * Wrapper component that protects admin-only routes
 * Checks if user has admin role before allowing access
 */
const AdminRoute: React.FC<AdminRouteProps> = ({ children }) => {
    const [checking, setChecking] = useState(true);
    const [isAdmin, setIsAdmin] = useState(false);

    useEffect(() => {
        checkAdminStatus();
    }, []);

    const checkAdminStatus = async () => {
        const token = localStorage.getItem('token');

        if (!token) {
            setIsAdmin(false);
            setChecking(false);
            return;
        }

        try {
            const response = await ApiService.request('/auth/me');
            const user = response?.data?.user;
            const role = user?.role;
            const hasServerAuthorizedRole = role === 'admin' || role === 'view';

            if (hasServerAuthorizedRole && user) {
                persistAdminPortalSession(user, token);
            }

            setIsAdmin(hasServerAuthorizedRole);

            if (!hasServerAuthorizedRole) {
                localStorage.removeItem('token');
                localStorage.removeItem('adminUser');
            }
        } catch (error) {
            console.error('Admin session validation failed:', error);
            localStorage.removeItem('token');
            localStorage.removeItem('adminUser');
            setIsAdmin(false);
        } finally {
            setChecking(false);
        }
    };

    if (checking) {
        return (
            <Box
                sx={{
                    display: 'flex',
                    justifyContent: 'center',
                    alignItems: 'center',
                    minHeight: '100vh',
                }}
            >
                <CircularProgress />
            </Box>
        );
    }

    if (!isAdmin) {
        return <Navigate to="/admin/login" replace />;
    }

    return <>{children}</>;
};

export default AdminRoute;
