import React from 'react';
import { Alert, AlertTitle, Box, Chip, List, ListItem, ListItemText, Typography } from '@mui/material';
import WarningAmberIcon from '@mui/icons-material/WarningAmber';

export interface OcrUserAction {
  action: 'reupload' | 'review_or_reupload' | string;
  message: string;
  missing_fields?: string[];
  problematic_sections?: string[];
  tips?: string[];
}

export interface OcrValidation {
  invoice_confidence?: number;
  ocr_quality_score?: number;
  low_confidence?: boolean;
  unreadable?: boolean;
  missing_fields?: string[];
  problematic_sections?: string[];
  blur_detected?: boolean;
  thermal_detection?: { is_thermal?: boolean; receipt_type?: string };
  user_action?: OcrUserAction | null;
}

interface OCRValidationBannerProps {
  validation?: OcrValidation | null;
  onDismiss?: () => void;
}

const sectionLabels: Record<string, string> = {
  gstin_block_unclear: 'GSTIN block unclear',
  total_amount_unclear: 'Total amount unclear',
  line_item_table_unclear: 'Line items table unclear',
  blurry_scan: 'Blurry scan',
  thermal_receipt: 'Thermal receipt'
};

const OCRValidationBanner: React.FC<OCRValidationBannerProps> = ({ validation, onDismiss }) => {
  if (!validation || (!validation.low_confidence && !validation.unreadable)) {
    return null;
  }

  const action = validation.user_action;
  const severity = validation.unreadable ? 'error' : 'warning';
  const confidencePct = Math.round((validation.invoice_confidence || 0) * 100);

  return (
    <Alert
      severity={severity}
      icon={<WarningAmberIcon />}
      onClose={onDismiss}
      sx={{ mb: 2 }}
    >
      <AlertTitle>
        {validation.unreadable ? 'Invoice difficult to read' : 'Low OCR confidence'}
        {confidencePct > 0 && (
          <Chip label={`${confidencePct}% confidence`} size="small" sx={{ ml: 1 }} />
        )}
      </AlertTitle>
      <Typography variant="body2" sx={{ mb: 1 }}>
        {action?.message ||
          'Some fields may be incorrect. Please verify or upload a clearer invoice.'}
      </Typography>
      {validation.missing_fields && validation.missing_fields.length > 0 && (
        <Box sx={{ mb: 1 }}>
          <Typography variant="caption" color="text.secondary">
            Missing or weak fields:
          </Typography>
          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mt: 0.5 }}>
            {validation.missing_fields.map((f) => (
              <Chip key={f} label={f.toUpperCase()} size="small" color="warning" variant="outlined" />
            ))}
          </Box>
        </Box>
      )}
      {validation.problematic_sections && validation.problematic_sections.length > 0 && (
        <Typography variant="caption" display="block" color="text.secondary">
          Issues: {validation.problematic_sections.map((s) => sectionLabels[s] || s).join(', ')}
        </Typography>
      )}
      {action?.tips && action.tips.length > 0 && (
        <List dense sx={{ py: 0 }}>
          {action.tips.map((tip) => (
            <ListItem key={tip} disablePadding>
              <ListItemText primary={`• ${tip}`} primaryTypographyProps={{ variant: 'caption' }} />
            </ListItem>
          ))}
        </List>
      )}
    </Alert>
  );
};

export default OCRValidationBanner;
