import { POST_LOGIN_IMAGES } from '../constants/postLoginPageImages';
import { resolvePageInfo } from './routePageMeta';

export interface PostLoginPageVisual {
  image: string;
  imageAlt: string;
  /** Screen-reader page title; visible UI is image-led. */
  title: string;
}

function readSection(search: string): string | null {
  if (!search) return null;
  return new URLSearchParams(search).get('section');
}

function readTab(search: string): number | null {
  if (!search) return null;
  const raw = new URLSearchParams(search).get('tab');
  if (raw === null || raw === '') return null;
  const parsed = Number.parseInt(raw, 10);
  return Number.isNaN(parsed) ? null : parsed;
}

function resolveByPathAndSearch(pathname: string, search: string): Pick<PostLoginPageVisual, 'image' | 'imageAlt'> | null {
  const path = pathname || '/';
  const section = readSection(search);
  const tab = readTab(search);

  if (path.startsWith('/dashboard')) {
    return {
      image: POST_LOGIN_IMAGES.home,
      imageAlt: 'Operational control center dashboard with emissions overview and workspace signals.',
    };
  }

  if (path.startsWith('/msme-profile')) {
    return {
      image: POST_LOGIN_IMAGES.profile,
      imageAlt: 'Company profile workspace with registration and manufacturing details.',
    };
  }

  if (path.startsWith('/operations')) {
    return {
      image: POST_LOGIN_IMAGES.operations,
      imageAlt: 'Manufacturing workflow planner for organizational and operational boundaries.',
    };
  }

  if (path.startsWith('/document-upload')) {
    return {
      image: POST_LOGIN_IMAGES.data,
      imageAlt: 'Document upload workspace for invoices, bills, and activity evidence.',
    };
  }

  if (path.startsWith('/msme-registration')) {
    return {
      image: POST_LOGIN_IMAGES.registration,
      imageAlt: 'MSME registration form capturing company and operational baseline details.',
    };
  }

  if (path.startsWith('/manufacturing-workflow')) {
    return {
      image: POST_LOGIN_IMAGES.operations,
      imageAlt: 'Manufacturing workflow mapping equipment and processes to emission drivers.',
    };
  }

  if (path.startsWith('/enterprise/dashboard')) {
    return {
      image: POST_LOGIN_IMAGES.enterprise,
      imageAlt: 'Enterprise control center with portfolio emissions and supplier signals.',
    };
  }

  if (path.startsWith('/enterprise/profile') || path.startsWith('/enterprise/registration')) {
    return {
      image: POST_LOGIN_IMAGES.profile,
      imageAlt: 'Enterprise organization profile and registration details.',
    };
  }

  if (path.startsWith('/enterprise/workflow')) {
    return {
      image: POST_LOGIN_IMAGES.operations,
      imageAlt: 'Enterprise compliance and operational workflow planner.',
    };
  }

  if (path.startsWith('/enterprise/data')) {
    if (section === 'connectors') {
      return {
        image: POST_LOGIN_IMAGES.dataConnectors,
        imageAlt: 'Enterprise accounting connectors importing supplier activity data.',
      };
    }
    return {
      image: POST_LOGIN_IMAGES.data,
      imageAlt: 'Enterprise document and activity data workspace.',
    };
  }

  if (path.startsWith('/enterprise/carbon-footprint')) {
    return {
      image: POST_LOGIN_IMAGES.carbonAssessment,
      imageAlt: 'Enterprise carbon inventory across scope 1, 2, and material scope 3 categories.',
    };
  }

  if (path.startsWith('/enterprise/compliance')) {
    return {
      image: POST_LOGIN_IMAGES.compliance,
      imageAlt: 'Enterprise BRSR and India market compliance readiness workspace.',
    };
  }

  if (path.startsWith('/enterprise/reporting')) {
    return {
      image: POST_LOGIN_IMAGES.reporting,
      imageAlt: 'Enterprise disclosure reports for regulators and stakeholders.',
    };
  }

  if (path.startsWith('/enterprise/pricing')) {
    return {
      image: POST_LOGIN_IMAGES.billing,
      imageAlt: 'Enterprise pricing and subscription plans overview.',
    };
  }

  if (
    path.startsWith('/multi-agent-management')
    || path.startsWith('/multi-agent-dashboard')
    || path.startsWith('/optimized-multi-agent-dashboard')
  ) {
    return {
      image: POST_LOGIN_IMAGES.operations,
      imageAlt: 'Multi-agent orchestration console for carbon intelligence workflows.',
    };
  }

  if (path.startsWith('/data') || path.startsWith('/document-management')) {
    if (section === 'connectors') {
      return {
        image: POST_LOGIN_IMAGES.dataConnectors,
        imageAlt: 'Accounting connectors importing activity data into the carbon workspace.',
      };
    }
    const dataTabAlts = [
      'Document library listing uploaded invoices and bills.',
      'Document management workspace for tagging and review.',
      'Duplicate detection queue for reconciled transactions.',
      'Processing pipeline status for OCR and carbon extraction.',
      'Data statistics and quality metrics for uploaded records.',
    ];
    const tabIndex = tab ?? 0;
    return {
      image: POST_LOGIN_IMAGES.data,
      imageAlt: dataTabAlts[tabIndex] ?? dataTabAlts[0],
    };
  }

  if (path.startsWith('/carbon-footprint')) {
    if (section === 'carbon-analytics') {
      return {
        image: POST_LOGIN_IMAGES.carbonAnalytics,
        imageAlt: 'Carbon analytics charts and trend visualizations.',
      };
    }
    return {
      image: POST_LOGIN_IMAGES.carbonAssessment,
      imageAlt: 'GHG assessment workspace for operational data, inputs, and results.',
    };
  }

  if (path.startsWith('/emissions-reduction-targets')) {
    const targetAlts = [
      'Emissions reduction progress charts against baselines.',
      'Target configuration for monthly, quarterly, and annual budgets.',
      'Recommendation list for reduction initiatives.',
    ];
    return {
      image: POST_LOGIN_IMAGES.emissionsTargets,
      imageAlt: targetAlts[tab ?? 0] ?? targetAlts[0],
    };
  }

  if (path.startsWith('/compliance/india')) {
    return {
      image: POST_LOGIN_IMAGES.complianceIndia,
      imageAlt: 'India market compliance track for BRSR, PAT, and domestic disclosures.',
    };
  }

  if (path.startsWith('/compliance/export')) {
    return {
      image: POST_LOGIN_IMAGES.complianceExport,
      imageAlt: 'Global export compliance track for CBAM, CSRD, and buyer questionnaires.',
    };
  }

  if (path.startsWith('/compliance')) {
    return {
      image: POST_LOGIN_IMAGES.compliance,
      imageAlt: 'Compliance hub overview with India and export readiness tracks.',
    };
  }

  if (path.startsWith('/reporting')) {
    return {
      image: POST_LOGIN_IMAGES.reporting,
      imageAlt: 'Disclosure reports module for BRSR, ISO, and CBAM PDF exports.',
    };
  }

  if (path.startsWith('/billing')) {
    return {
      image: POST_LOGIN_IMAGES.billing,
      imageAlt: 'Billing and payments workspace with plan and usage details.',
    };
  }

  if (path.startsWith('/information')) {
    return {
      image: POST_LOGIN_IMAGES.information,
      imageAlt: 'Product information, user manual, and frequently asked questions.',
    };
  }

  if (path.startsWith('/settings')) {
    return {
      image: POST_LOGIN_IMAGES.settings,
      imageAlt: 'Account settings and workspace preferences.',
    };
  }

  if (path.startsWith('/data-privacy')) {
    return {
      image: POST_LOGIN_IMAGES.dataPrivacy,
      imageAlt: 'Data privacy controls for identifiers and document processing.',
    };
  }

  if (path.startsWith('/help')) {
    return {
      image: POST_LOGIN_IMAGES.help,
      imageAlt: 'Help center guidance for carbon workspace tasks.',
    };
  }

  if (path.startsWith('/green-loans')) {
    return {
      image: POST_LOGIN_IMAGES.greenLoans,
      imageAlt: 'Green financing summaries for lender-ready emissions evidence.',
    };
  }

  if (
    path.startsWith('/carbon-marketplace')
    || path.startsWith('/carbon-credits')
    || path.startsWith('/carbon-trading')
  ) {
    return {
      image: POST_LOGIN_IMAGES.carbonCredits,
      imageAlt: 'Carbon credits portfolio, trading, and retirement balances.',
    };
  }

  if (path.startsWith('/carbon-savings')) {
    return {
      image: POST_LOGIN_IMAGES.carbonSavings,
      imageAlt: 'Carbon savings dashboard comparing avoided emissions over time.',
    };
  }

  if (path.startsWith('/carbon-forecasting')) {
    return {
      image: POST_LOGIN_IMAGES.carbonForecasting,
      imageAlt: 'Carbon forecasting graph projecting emissions scenarios.',
    };
  }

  if (path.startsWith('/gift-schemes') || path.startsWith('/gift-applications')) {
    return {
      image: POST_LOGIN_IMAGES.gift,
      imageAlt: 'GIFT scheme applications and eligibility workflows.',
    };
  }

  return null;
}

export function resolvePostLoginPageVisual(pathname: string, search = ''): PostLoginPageVisual {
  const info = resolvePageInfo(pathname);
  const matched = resolveByPathAndSearch(pathname, search);

  if (matched) {
    return {
      title: info.title,
      ...matched,
    };
  }

  return {
    title: info.title,
    image: POST_LOGIN_IMAGES.home,
    imageAlt: info.pageDescription,
  };
}
