import React, { useCallback, useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import ApiService from '../services/api';
import { hasCompletedEnterpriseWorkflow } from '../utils/enterpriseWorkflowCompletion';
import RouteLoadingGate from './RouteLoadingGate';

interface RequireEnterpriseWorkflowProps {
  children: React.ReactNode;
}

const RequireEnterpriseWorkflow: React.FC<RequireEnterpriseWorkflowProps> = ({ children }) => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [complete, setComplete] = useState(false);

  const checkWorkflow = useCallback(async () => {
    try {
      const response = await ApiService.getEnterpriseWorkflow();
      const sections = response?.data?.sections;
      if (hasCompletedEnterpriseWorkflow(sections)) {
        setComplete(true);
      } else {
        navigate('/enterprise/workflow');
      }
    } catch {
      navigate('/enterprise/workflow');
    } finally {
      setLoading(false);
    }
  }, [navigate]);

  useEffect(() => {
    checkWorkflow();
  }, [checkWorkflow]);

  if (loading) {
    return <RouteLoadingGate message="Loading compliance workflow…" minHeight="400px" />;
  }

  return complete ? <>{children}</> : null;
};

export default RequireEnterpriseWorkflow;
