import React, { useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Checkbox,
  CircularProgress,
  FormControlLabel,
  Grid,
  MenuItem,
  Paper,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { alpha, useTheme } from '@mui/material/styles';
import { useNavigate } from 'react-router-dom';
import ApiService from '../services/api';
import { ProfileCompletenessCard } from './shared/ProfileCompletenessCard';
import { computeMsmeProfileCompleteness } from '../utils/sustainabilityUx';
interface MSMEProfileData {
  _id?: string;
  companyName?: string;
  companyType?: string;
  industry?: string;
  businessDomain?: string;
  udyamRegistrationNumber?: string;
  gstNumber?: string;
  panNumber?: string;
  contact?: {
    email?: string;
    phone?: string;
    address?: {
      street?: string;
      city?: string;
      state?: string;
      pincode?: string;
      country?: string;
    };
  };
  business?: {
    annualTurnover?: number;
    numberOfEmployees?: number;
    manufacturingUnits?: number;
    manufacturingWorkflow?: any;
    solarPower?: {
      installedCapacityKw?: number;
      annualGenerationKwh?: number;
      annualUsageKwh?: number;
      netMeteringEnabled?: boolean;
      lastUpdatedAt?: string;
    };
  };
  manufacturingProfile?: {
    msmeType?: string;
    industrySector?: string;
    nicCode?: string;
    yearOfEstablishment?: number;
    locationCity?: string;
    locationState?: string;
    locationCountry?: string;
    numberOfEmployees?: number;
    plantAreaSqft?: number;
    operationalDaysPerYear?: number;
    primaryEnergySource?: string;
    backupEnergySource?: string;
    mainFuelsUsed?: string[];
    waterSource?: string;
    wasteManagementPractice?: string;
    keyProducts?: string[];
    productionCapacityPerMonth?: number;
    productionCapacityUnit?: string;
    supplyChainType?: string;
    logisticsMode?: string;
    certifications?: string[];
    esgMaturityLevel?: string;
    digitalizationLevel?: string;
    carbonAccountingPractice?: string;
    powerConsumptionKwhPerMonth?: number;
    waterConsumptionKlPerMonth?: number;
    chemicalsConsumptionKgPerMonth?: number;
    wasteRecycledKgPerMonth?: number;
    wasteWaterKlPerMonth?: number;
    solarInstallationKw?: number;
    solarGenerationKwhPerMonth?: number;
    importedRawMaterialsKgPerMonth?: number;
    outputProductsKgPerMonth?: number;
    servicesDeliveredPerMonth?: number;
    complianceCertifications?: string[];
    iso14064Aligned?: boolean;
    iso14067Aligned?: boolean;
    ghgProtocolAligned?: boolean;
    regulatoryExposure?: string[];
    exportActivity?: boolean;
    clusterAssociation?: string;
    ghgOrganizationalBoundary?: {
      consolidationApproach?: string;
      reportingEntityDescription?: string;
      includedLegalEntities?: Array<{
        name?: string;
        relationshipType?: string;
        consolidationBasis?: string;
      }>;
      jointVentureEmissionAllocation?: string;
      franchisesOrOutsourcedOperationsTreatment?: string;
      nonControlledOperationsExcluded?: boolean;
      organizationalBoundaryNotes?: string;
      lastReviewedAt?: string;
    };
  };
  operations?: {
    sites?: Array<{
      name?: string;
      city?: string;
      state?: string;
      country?: string;
    }>;
    vehicles?: Array<{
      type?: string;
      fuelType?: string;
      ownership?: string;
      count?: number;
      monthlyDistanceKm?: number;
    }>;
    subsidiaries?: Array<{
      name?: string;
      controlModel?: string;
    }>;
    metrics?: {
      powerConsumptionKwhPerMonth?: number;
      waterConsumptionKlPerMonth?: number;
      chemicalsConsumptionKgPerMonth?: number;
      fuelUsageLitersPerMonth?: number;
      recycledWasteKgPerMonth?: number;
      wasteWaterKlPerMonth?: number;
      solarInstallationKw?: number;
      solarGenerationKwhPerMonth?: number;
      importedRawMaterialsKgPerMonth?: number;
      outputProductsKgPerMonth?: number;
      servicesDeliveredPerMonth?: number;
      annualTurnoverInr?: number;
      complianceCertifications?: string[];
      iso14064Aligned?: boolean;
      iso14067Aligned?: boolean;
      ghgProtocolAligned?: boolean;
    };
    operationsDataFeed?: {
      selectedChemicalOptions?: string[];
      selectedWaterTreatmentOptions?: string[];
    };
    ghgOperationalBoundary?: {
      reportingPeriodType?: string;
      reportingPeriodEndMonth?: number;
      baseYear?: number;
      materialityThresholdPercent?: number;
      scope1StationaryCombustion?: boolean;
      scope1MobileCombustion?: boolean;
      scope1ProcessEmissions?: boolean;
      scope1FugitiveEmissions?: boolean;
      scope2LocationBased?: boolean;
      scope2MarketBased?: boolean;
      scope3CategoriesIncluded?: number[];
      scope3OutOfBoundarySummary?: string;
      biogenicCo2Approach?: string;
      operationalBoundaryDefinitionSummary?: string;
      operationalBoundaryNotes?: string;
    };
  };
}

/** Side-by-side view of consolidation scope vs. excluded related parties (GHG Protocol organizational boundary). */
function GhgOrganizationalBoundaryVisual() {
  const theme = useTheme();
  return (
    <Paper
      variant="outlined"
      component="figure"
      sx={{
        mb: 2,
        p: 2,
        bgcolor: 'action.hover',
        borderStyle: 'dashed',
      }}
      aria-label="Diagram comparing operations outside versus inside the organizational boundary for GHG inventory consolidation."
    >
      <Typography component="figcaption" variant="subtitle2" sx={{ fontWeight: 700, mb: 1.5 }}>
        Scope visualization: organizational boundary (which operations belong in your inventory)
      </Typography>
      <Grid container spacing={2}>
        <Grid item xs={12} md={6}>
          <Box
            sx={{
              p: 2,
              height: '100%',
              borderRadius: 1,
              border: '1px solid',
              borderColor: 'divider',
              bgcolor: 'background.paper',
            }}
          >
            <Typography variant="caption" color="text.secondary" sx={{ fontWeight: 700, textTransform: 'uppercase', letterSpacing: 0.06 }}>
              Outside consolidation (examples)
            </Typography>
            <Stack spacing={1} sx={{ mt: 1 }}>
              <Box
                sx={{
                  py: 0.75,
                  px: 1,
                  borderRadius: 1,
                  bgcolor: 'action.selected',
                  border: '1px dashed',
                  borderColor: 'text.disabled',
                }}
              >
                <Typography variant="body2">Third-party suppliers and contractors</Typography>
                <Typography variant="caption" color="text.secondary">
                  Their on-site emissions are not consolidated into your organizational inventory.
                </Typography>
              </Box>
              <Box
                sx={{
                  py: 0.75,
                  px: 1,
                  borderRadius: 1,
                  bgcolor: 'action.selected',
                  border: '1px dashed',
                  borderColor: 'text.disabled',
                }}
              >
                <Typography variant="body2">Non-controlled JVs, franchisees, toll manufacturers</Typography>
                <Typography variant="caption" color="text.secondary">
                  In or out depends on operational / financial control or equity share — document your treatment below.
                </Typography>
              </Box>
            </Stack>
          </Box>
        </Grid>
        <Grid item xs={12} md={6}>
          <Box
            sx={{
              p: 2,
              height: '100%',
              borderRadius: 1,
              border: `2px solid ${theme.palette.primary.main}`,
              bgcolor: alpha(theme.palette.primary.main, 0.06),
            }}
          >
            <Typography variant="caption" sx={{ fontWeight: 700, textTransform: 'uppercase', letterSpacing: 0.06, color: 'primary.main' }}>
              Inside consolidation (your GHG inventory)
            </Typography>
            <Stack spacing={1} sx={{ mt: 1 }}>
              <Box
                sx={{
                  py: 0.75,
                  px: 1,
                  borderRadius: 1,
                  bgcolor: 'background.paper',
                  border: '1px solid',
                  borderColor: 'primary.light',
                }}
              >
                <Typography variant="body2" fontWeight={600}>
                  Reporting legal entity and consolidated operations
                </Typography>
                <Typography variant="caption" color="text.secondary">
                  Plants, branches, warehouses, and subsidiaries included under your chosen consolidation approach.
                </Typography>
              </Box>
            </Stack>
          </Box>
        </Grid>
      </Grid>
    </Paper>
  );
}

const MSMEProfileSection: React.FC = () => {
  const navigate = useNavigate();
  const [profile, setProfile] = useState<MSMEProfileData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [orgBoundaryDraft, setOrgBoundaryDraft] = useState({
    consolidationApproach: 'operational_control',
    reportingEntityDescription: '',
    jointVentureEmissionAllocation: 'not_applicable',
    franchisesOrOutsourcedOperationsTreatment: '',
    nonControlledOperationsExcluded: true,
    organizationalBoundaryNotes: ''
  });
  const [orgBoundarySaving, setOrgBoundarySaving] = useState(false);
  const [orgBoundaryFeedback, setOrgBoundaryFeedback] = useState<string | null>(null);

  useEffect(() => {
    const loadProfile = async () => {
      setLoading(true);
      setError(null);
      try {
        const response = await ApiService.getMSMEProfile();
        setProfile(response?.data || null);
      } catch (err) {
        setProfile(null);
        setError(err instanceof Error ? err.message : 'Unable to load MSME profile.');
      } finally {
        setLoading(false);
      }
    };

    loadProfile();
  }, []);

  useEffect(() => {
    if (!profile) return;
    const ob = profile.manufacturingProfile?.ghgOrganizationalBoundary;
    if (ob && typeof ob === 'object') {
      setOrgBoundaryDraft({
        consolidationApproach: ob.consolidationApproach || 'operational_control',
        reportingEntityDescription: String(ob.reportingEntityDescription || ''),
        jointVentureEmissionAllocation: ob.jointVentureEmissionAllocation || 'not_applicable',
        franchisesOrOutsourcedOperationsTreatment: String(ob.franchisesOrOutsourcedOperationsTreatment || ''),
        nonControlledOperationsExcluded: ob.nonControlledOperationsExcluded !== false,
        organizationalBoundaryNotes: String(ob.organizationalBoundaryNotes || '')
      });
    }
  }, [profile]);

  const saveOrganizationalBoundary = async () => {
    if (!profile) return;
    setOrgBoundarySaving(true);
    setOrgBoundaryFeedback(null);
    try {
      const prevIncluded = profile.manufacturingProfile?.ghgOrganizationalBoundary?.includedLegalEntities;
      await ApiService.updateMSMEProfile({
        manufacturingProfile: {
          ...(profile.manufacturingProfile || {}),
          ghgOrganizationalBoundary: {
            consolidationApproach: orgBoundaryDraft.consolidationApproach,
            reportingEntityDescription: orgBoundaryDraft.reportingEntityDescription,
            includedLegalEntities: Array.isArray(prevIncluded) ? prevIncluded : [],
            jointVentureEmissionAllocation: orgBoundaryDraft.jointVentureEmissionAllocation,
            franchisesOrOutsourcedOperationsTreatment: orgBoundaryDraft.franchisesOrOutsourcedOperationsTreatment,
            nonControlledOperationsExcluded: orgBoundaryDraft.nonControlledOperationsExcluded,
            organizationalBoundaryNotes: orgBoundaryDraft.organizationalBoundaryNotes,
            lastReviewedAt: new Date().toISOString()
          }
        }
      });
      const response = await ApiService.getMSMEProfile();
      setProfile(response?.data || null);
      setOrgBoundaryFeedback('Organizational boundary saved to your profile.');
    } catch (err) {
      setOrgBoundaryFeedback(err instanceof Error ? err.message : 'Unable to save organizational boundary.');
    } finally {
      setOrgBoundarySaving(false);
    }
  };

  const profileAddress = [
    profile?.contact?.address?.street,
    profile?.contact?.address?.city,
    profile?.contact?.address?.state,
    profile?.contact?.address?.pincode,
    profile?.contact?.address?.country,
  ]
    .filter(Boolean)
    .join(', ');

  const profileCompleteness = useMemo(
    () => computeMsmeProfileCompleteness(profile as unknown as Record<string, unknown>),
    [profile]
  );

  return (
    <Box>
      <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
        View and manage registration details, manufacturing attributes, and your GHG organizational boundary. Operational
        resource data and workflow configuration live on the Operations page.
      </Typography>

      {profile && !loading && (
        <ProfileCompletenessCard
          result={profileCompleteness}
          actionPath="/operations"
          actionLabel="Complete operations setup"
        />
      )}

      {loading ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', py: 6 }}>
              <CircularProgress />
            </Box>
          ) : error ? (
            <Alert severity="warning" sx={{ mb: 2 }}>
              {error}
            </Alert>
          ) : !profile ? (
            <Alert
              severity="info"
              action={(
                <Button color="inherit" size="small" onClick={() => navigate('/msme-registration')}>
                  Complete registration
                </Button>
              )}
            >
              MSME profile is not available yet.
            </Alert>
          ) : (
            <Grid container spacing={2}>
              <Grid item xs={12}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
                      Company Information
                    </Typography>
                    <Grid container spacing={2}>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Business Domain</Typography>
                        <Typography variant="body1">{profile.businessDomain || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Company Name</Typography>
                        <Typography variant="body1">{profile.companyName || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Company Type</Typography>
                        <Typography variant="body1">{profile.companyType || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Contact Email</Typography>
                        <Typography variant="body1">{profile.contact?.email || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Digitalization Level</Typography>
                        <Typography variant="body1">{profile.manufacturingProfile?.digitalizationLevel || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">ESG Maturity</Typography>
                        <Typography variant="body1">{profile.manufacturingProfile?.esgMaturityLevel || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Export Activity</Typography>
                        <Typography variant="body1">
                          {profile.manufacturingProfile?.exportActivity === undefined
                            ? 'Not provided'
                            : profile.manufacturingProfile?.exportActivity ? 'Yes' : 'No'}
                        </Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">GST Number</Typography>
                        <Typography variant="body1">{profile.gstNumber || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Industry</Typography>
                        <Typography variant="body1">{profile.industry || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">NIC Code</Typography>
                        <Typography variant="body1">{profile.manufacturingProfile?.nicCode || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Operational Days / Year</Typography>
                        <Typography variant="body1">
                          {profile.manufacturingProfile?.operationalDaysPerYear ?? 'Not provided'}
                        </Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">PAN Number</Typography>
                        <Typography variant="body1">{profile.panNumber || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Primary Energy Source</Typography>
                        <Typography variant="body1">{profile.manufacturingProfile?.primaryEnergySource || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Udyog Number (UDYAM)</Typography>
                        <Typography variant="body1">{profile.udyamRegistrationNumber || 'Not provided'}</Typography>
                      </Grid>
                    </Grid>
                  </CardContent>
                </Card>
              </Grid>

              <Grid item xs={12}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 1 }}>
                      Organizational boundary (GHG Protocol)
                    </Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                      The organizational boundary identifies which companies, joint ventures, and operations are consolidated into
                      one inventory using operational control, financial control, or equity share. This is distinct from the
                      operational boundary configured under Operations → GHG boundaries.
                    </Typography>
                    <GhgOrganizationalBoundaryVisual />
                    {orgBoundaryFeedback && (
                      <Alert severity={orgBoundaryFeedback.includes('saved') ? 'success' : 'warning'} sx={{ mb: 2 }}>
                        {orgBoundaryFeedback}
                      </Alert>
                    )}
                    <Grid container spacing={2}>
                      <Grid item xs={12} md={6}>
                        <TextField
                          select
                          fullWidth
                          label="Consolidation approach"
                          value={orgBoundaryDraft.consolidationApproach}
                          onChange={(e) => setOrgBoundaryDraft((d) => ({ ...d, consolidationApproach: e.target.value }))}
                        >
                          <MenuItem value="operational_control">Operational control</MenuItem>
                          <MenuItem value="financial_control">Financial control</MenuItem>
                          <MenuItem value="equity_share">Equity share</MenuItem>
                        </TextField>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <TextField
                          select
                          fullWidth
                          label="Joint venture emissions allocation"
                          value={orgBoundaryDraft.jointVentureEmissionAllocation}
                          onChange={(e) => setOrgBoundaryDraft((d) => ({ ...d, jointVentureEmissionAllocation: e.target.value }))}
                        >
                          <MenuItem value="not_applicable">Not applicable</MenuItem>
                          <MenuItem value="proportional_equity">Proportional to equity share</MenuItem>
                          <MenuItem value="operational_share">By operational share</MenuItem>
                        </TextField>
                      </Grid>
                      <Grid item xs={12}>
                        <TextField
                          fullWidth
                          multiline
                          minRows={2}
                          label="Reporting entity and included operations"
                          value={orgBoundaryDraft.reportingEntityDescription}
                          onChange={(e) => setOrgBoundaryDraft((d) => ({ ...d, reportingEntityDescription: e.target.value }))}
                          placeholder="Describe the legal reporting entity and which branches, plants, or divisions are consolidated."
                        />
                      </Grid>
                      <Grid item xs={12}>
                        <TextField
                          fullWidth
                          multiline
                          minRows={2}
                          label="Franchises, outsourced operations, or shared sites"
                          value={orgBoundaryDraft.franchisesOrOutsourcedOperationsTreatment}
                          onChange={(e) => setOrgBoundaryDraft((d) => ({
                            ...d,
                            franchisesOrOutsourcedOperationsTreatment: e.target.value
                          }))}
                          placeholder="State whether franchised outlets, toll manufacturers, or 3PL sites are in or out of the boundary."
                        />
                      </Grid>
                      <Grid item xs={12}>
                        <FormControlLabel
                          control={(
                            <Checkbox
                              checked={orgBoundaryDraft.nonControlledOperationsExcluded}
                              onChange={(e) => setOrgBoundaryDraft((d) => ({
                                ...d,
                                nonControlledOperationsExcluded: e.target.checked
                              }))}
                            />
                          )}
                          label="Operations we do not financially or operationally control are excluded from this inventory"
                        />
                      </Grid>
                      <Grid item xs={12}>
                        <TextField
                          fullWidth
                          multiline
                          minRows={2}
                          label="Organizational boundary notes"
                          value={orgBoundaryDraft.organizationalBoundaryNotes}
                          onChange={(e) => setOrgBoundaryDraft((d) => ({ ...d, organizationalBoundaryNotes: e.target.value }))}
                        />
                      </Grid>
                      <Grid item xs={12}>
                        <Stack direction="row" spacing={1}>
                          <Button variant="contained" onClick={saveOrganizationalBoundary} disabled={orgBoundarySaving}>
                            {orgBoundarySaving ? 'Saving…' : 'Save organizational boundary'}
                          </Button>
                        </Stack>
                      </Grid>
                    </Grid>
                  </CardContent>
                </Card>
              </Grid>

              <Grid item xs={12}>
                <Alert
                  severity="info"
                  action={(
                    <Button color="inherit" size="small" onClick={() => navigate('/operations')}>
                      Open operations
                    </Button>
                  )}
                >
                  Monthly resource use, GHG operational boundaries, manufacturing workflow, and framework alignment are
                  maintained on the Operations page so they are not duplicated here.
                </Alert>
              </Grid>

              <Grid item xs={12}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 1.5 }}>
                      Company Location and Registration Snapshot
                    </Typography>
                    <Grid container spacing={2}>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Registered Address</Typography>
                        <Typography variant="body1">{profileAddress || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Plant Location</Typography>
                        <Typography variant="body1">
                          {[profile.manufacturingProfile?.locationCity, profile.manufacturingProfile?.locationState, profile.manufacturingProfile?.locationCountry]
                            .filter(Boolean)
                            .join(', ') || 'Not provided'}
                        </Typography>
                      </Grid>
                    </Grid>
                  </CardContent>
                </Card>
              </Grid>
            </Grid>
          )}
    </Box>
  );
};

export default MSMEProfileSection;
